    sr = [r for r in range(h) if len(set(grid[r])) == 1]
    sc = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    def spans(n, seps):
        ans, start = [], 0
        for s in seps:
            if start < s:
                ans.append((start, s))
            start = s + 1
        if start < n:
            ans.append((start, n))
        return ans
    result = []
    for r0, r1 in spans(h, sr):
        row = []
        for c0, c1 in spans(w, sc):
            pixels = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            # 7 is the tile background; mark exactly two contrasting cells.
            row.append(int(sum(x != 7 for x in pixels) == 2))
        result.append(row)
    return result

