 "content": "from collections import Counter

def transform(grid):
    h,w=len(grid),len(grid[0])
    # 0 divider lines are full-zero rows and columns; ignore the colored
    # perimeter on the demo's last row/column by identifying regular bars.
    sr=[r for r in range(h) if all(x==0 for x in grid[r])]
    sc=[c for c in range(w) if all(grid[r][c]==0 for r in range(h))]
    def spans(n,ds):
        out=[];s=0
        for d in ds:
            if s<d: out.append((s,d))
            s=d+1
        if s<n: out.append((s,n))
        return out
    rb,cb=spans(h,sr),spans(w,sc)
    # Locate dominant background, counting only non-divider cells.
    vals=[grid[r][c] for r0,r1 in rb for c0,c1 in cb for r in range(r0,r1) for c in range(c0,c1)]
    bg=Counter(vals).most_common(1)[0][0]
    out=[]
    for r0,r1 in rb:
        row=[]
        for c0,c1 in cb:
            n=sum(grid[r][c]!=bg for r in range(r0,r1) for c in range(c0,c1))
            row.append(int(n==2))
        out.append(row)
    return out

if __name__=='__main__': print('ready')
