 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    # Divider lines are the most frequent uniform rows/columns, which can
    # include a uniform-colored edge in these patterned grids.
    row_counts = Counter(tuple(row) for row in grid)
    row_seps = [r for r, row in enumerate(grid) if len(set(row)) == 1]
    col_seps = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(n, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < n:
            result.append((start, n))
        return result

    rb, cb = spans(h, row_seps), spans(w, col_seps)
    panels = []
    for r0, r1 in rb:
        line = []
        for c0, c1 in cb:
            counts = Counter(grid[r][c] for r in range(r0, r1) for c in range(c0, c1))
            bg = counts.most_common(1)[0][0]
            line.append((r0, r1, c0, c1, bg))
        panels.append(line)

    # Encode each panel by its unusual-cell count: the demos show singleton
    # panels use background-color values and paired panels are the positive mark.
    output = []
    for line in panels:
        out_line = []
        for r0, r1, c0, c1, bg in line:
            nonbg = [(r, c, grid[r][c]) for r in range(r0, r1) for c in range(c0, c1) if grid[r][c] != bg]
            if len(nonbg) == 2:
                out_line.append(1)
            elif len(nonbg) == 1:
                out_line.append(nonbg[0][2])
            else:
                out_line.append(0)
        output.append(out_line)
    return output

if __name__ == '__main__':
    print('ready')
