 "content": "from collections import Counter

def transform(grid):
    h, w = len(grid), len(grid[0])
    row_dividers = [r for r in range(h) if len(set(grid[r])) == 1]
    col_dividers = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]

    def spans(size, dividers):
        result, start = [], 0
        for d in dividers:
            if start < d:
                result.append((start, d))
            start = d + 1
        if start < size:
            result.append((start, size))
        return result

    row_spans = spans(h, row_dividers)
    col_spans = spans(w, col_dividers)
    output = []
    for r0, r1 in row_spans:
        row = []
        for c0, c1 in col_spans:
            panel = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            background = Counter(panel).most_common(1)[0][0]
            object_count = sum(value != background for value in panel)
            row.append(1 if object_count == 2 else background)
        output.append(row)
    return output

