 "content": "def transform(grid):
    # Panels separated by uniform divider rows/columns. Encode the count of
    # colored markers: zero -> 0, one -> panel background, two -> 1 or 3
    # depending on marker geometry.
    h, w = len(grid), len(grid[0])
    rdiv = [r for r in range(h) if len(set(grid[r])) == 1]
    cdiv = [c for c in range(w) if len({grid[r][c] for r in range(h)}) == 1]
    def spans(n, ds):
        out, start = [], 0
        for d in ds:
            if start < d: out.append((start, d))
            start = d + 1
        if start < n: out.append((start, n))
        return out
    out = []
    for r0, r1 in spans(h, rdiv):
        row = []
        for c0, c1 in spans(w, cdiv):
            vals = [grid[r][c] for r in range(r0, r1) for c in range(c0, c1)]
            bg = max(set(vals), key=vals.count)
            pts = [(r,c) for r in range(r0,r1) for c in range(c0,c1) if grid[r][c] != bg]
            if len(pts) == 1:
                row.append(bg)
            elif len(pts) == 2:
                # aligned in a column -> one, other pair -> three
                row.append(1 if pts[0][1] == pts[1][1] else 3)
            else:
                row.append(0)
        out.append(row)
    return out

